import { useState } from "react";
import { motion } from "framer-motion";
import {
  FaFileInvoiceDollar,
  FaBalanceScale,
  FaClipboardCheck,
  FaBookOpen
} from "react-icons/fa";

import Modal from "./Modal"; // make sure Modal.jsx is in the same folder OR adjust path

const services = [
  {
    title: "Tax Services (Individuals, Businesses and Not-for-Profit Organizations)",
    description: `Our firm provides specialized offshore support for preparing U.S. tax returns...`,
    icon: <FaFileInvoiceDollar className="text-6xl text-green-900" />,
    modalContent: (
      <div>
        <h3 className="font-semibold text-lg mb-2">Individual Tax Returns</h3>
        <p>We prepare and file federal, state, and local income tax returns for individuals:</p>
        <ul className="list-disc ml-6 mt-2">
          <li>Form 1040</li>
          <li>Schedule A</li>
          <li>Schedule B</li>
          <li>Schedule C</li>
          <li>Schedule D</li>
          <li>Schedule E</li>
          <li>Schedule F</li>
        </ul>

        <h3 className="font-semibold text-lg mt-4 mb-2">Business Tax Returns</h3>
        <ul className="list-disc ml-6">
          <li>Form 1120 (Corporation)</li>
          <li>Form 1120S (S-Corporation)</li>
          <li>Form 1065 (Partnership)</li>
        </ul>

        <h3 className="font-semibold text-lg mt-4 mb-2">Nonprofit Tax Filings</h3>
        <ul className="list-disc ml-6">
          <li>Form 990</li>
          <li>CHAR500 / CHAR660 (NY State charity filings)</li>
        </ul>
      </div>
    )
  },

  {
    title: "Audit & Attest Services",
    description: `Our firm offers audit and attest services across industries...`,
    icon: <FaBalanceScale className="text-6xl text-green-900" />,
  },

  {
    title: "Compilations and Agreed Upon Procedures",
    description: `We offer comprehensive compilations and agreed-upon procedures services...`,
    icon: <FaClipboardCheck className="text-6xl text-green-900" />,
  },

  {
    title: "Bookkeeping & Accounting Services",
    description: `We provide US bookkeeping and accounting services...`,
    icon: <FaBookOpen className="text-6xl text-green-900" />,
  }
];

export default function Services() {
  const [openModal, setOpenModal] = useState(null);

  return (
    <section id="services" className="py-20 bg-white px-6">
      <h2 className="text-5xl font-bold text-green-800 text-center mt-20 mb-20">
        Our Services
      </h2>

      <div className="grid gap-10 grid-cols-1 sm:grid-cols-2 max-w-6xl mx-auto">
        {services.map((service, i) => (
          <motion.div
            key={i}
            initial={{ opacity: 0, y: 40 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, delay: i * 0.1 }}
            whileHover={{ scale: 1.05 }}
            className="bg-white rounded-2xl p-8 border border-gray-200 shadow-md hover:shadow-2xl hover:border-cyan-700 hover:shadow-cyan-400/50 transition-all duration-300"
          >
            <div className="flex flex-col items-center text-center">
              <div className="mb-4">{service.icon}</div>
              <h3 className="text-lg font-bold text-gray-800 mb-2">{service.title}</h3>
              <p className="text-gray-700 text-sm mb-6">{service.description}</p>

              {service.modalContent && (
                <button
                  onClick={() => setOpenModal(i)}
                  className="inline-block px-5 py-2 text-sm font-semibold text-white bg-green-700 rounded-lg hover:bg-green-800 transition"
                >
                  Learn More
                </button>
              )}
            </div>
          </motion.div>
        ))}
      </div>

      {openModal !== null && (
        <Modal
          isOpen={true}
          title={services[openModal].title}
          onClose={() => setOpenModal(null)}
        >
          {services[openModal].modalContent}
        </Modal>
      )}
    </section>
  );
}
